-- Guarded correction of published educational drug cards. No private data.
-- Idempotent: exact before/after fields only. Divergence aborts the transaction.
DO $clinical$
DECLARE
  existing jsonb;
BEGIN
  SELECT jsonb_build_object('adult_bolus_dose', d.adult_bolus_dose, 'dosing', d.dosing, 'key_warning', d.key_warning, 'preparation', d.preparation, 'infusion_standard', d.infusion_standard, 'sources', d.sources) INTO STRICT existing FROM public.drugs AS d WHERE d.id='a03049d0-115e-4b01-915d-10c0a73910eb'::uuid AND d.slug='adrenaline' FOR UPDATE;
  IF existing = '{"adult_bolus_dose":"Adult cardiac arrest: 1 mg IV/IO of 0.1 mg/mL under the adult ALS algorithm, repeated every 3–5 minutes. Follow the rhythm-specific timing of the first dose.\nAdults with suspected anaphylaxis and a pulse: give 500 micrograms IM (0.5 mL of 1 mg/mL) in the anterolateral thigh. If airway, breathing or circulation problems persist, repeat after 5 minutes. In refractory anaphylaxis seek expert help for a monitored IV adrenaline infusion. An IV bolus in a patient with a pulse is restricted to appropriately experienced clinicians in an appropriate specialist setting.\nFor perioperative anaphylaxis or vasopressor support during anaesthesia, use the dedicated monitored specialist pathway.","dosing":"Adult cardiac arrest: 1 mg IV/IO of 0.1 mg/mL under the adult ALS algorithm, repeated every 3–5 minutes. Follow the rhythm-specific timing of the first dose.\nAdults with suspected anaphylaxis and a pulse: give 500 micrograms IM (0.5 mL of 1 mg/mL) in the anterolateral thigh. If airway, breathing or circulation problems persist, repeat after 5 minutes. In refractory anaphylaxis seek expert help for a monitored IV adrenaline infusion. An IV bolus in a patient with a pulse is restricted to appropriately experienced clinicians in an appropriate specialist setting.\nPaediatric anaphylaxis with a pulse, IM 1 mg/mL: under 6 months 100–150 micrograms; 6 months to under 6 years 150 micrograms; 6–12 years 300 micrograms; over 12 years 500 micrograms, or 300 micrograms for a small or prepubertal child. Repeat after 5 minutes for persistent airway, breathing or circulation problems.\nPaediatric cardiac arrest outside the newborn-at-birth pathway: 10 micrograms/kg IV/IO (0.1 mL/kg of 0.1 mg/mL), maximum 1 mg, every 3–5 minutes according to the PALS algorithm. Titrate vasoactive infusions in critical care to the specific indication, haemodynamics and local concentration protocol.","key_warning":"Confirm the route, concentration in mg/mL and indication. IM anaphylaxis uses 1 mg/mL. Adult cardiac arrest uses 0.1 mg/mL for a 1 mg IV/IO dose. Never give an IM-size dose intravenously to a patient with a pulse.","preparation":"Adult critical-care infusion example from the NHS injectable-medicines guide: 4 mg in a FINAL volume of 50 mL gives 80 micrograms/mL. Using 1 mg/mL stock, withdraw 4 mL and add compatible diluent to a final volume of 50 mL. Prefer a ready-prepared infusion where available. Check the actual label, access and local policy before programming the pump. This concentration is separate from the RCUK refractory-anaphylaxis infusion protocol.\nFor IM anaphylaxis use 1 mg/mL undiluted. For IV/IO cardiac-arrest dosing, use the labelled 0.1 mg/mL solution. Administration to a patient with a pulse requires an indication-specific specialist protocol.","infusion_standard":{"amount_mg":4,"diluent_ml":50,"unit":"mcg/kg/min","weight_based":true,"note":"NHS critical-care example: 4 mg in FINAL 50 mL = 80 micrograms/mL. Verify actual concentration."},"sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Adrenaline (epinephrine) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=adrenaline"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Adrenaline (epinephrine) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=adrenaline"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Adrenaline (epinephrine) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=adrenaline"},{"accessed":"2026-09-13","publisher":"Critical Care Medicine / SCCM–ESICM","title":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021","url":"https://doi.org/10.1097/CCM.0000000000005337"},{"title":"Adult resuscitation in special circumstances, 2025: anaphylaxis","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines","publisher":"Resuscitation Council UK","accessed":"2026-11-19"},{"title":"Emergency treatment of anaphylaxis: IM dosing by age, repeat dose and refractory treatment","url":"https://www.resus.org.uk/sites/default/files/2021-05/Emergency%20Treatment%20of%20Anaphylaxis%20May%202021_0.pdf","publisher":"Resuscitation Council UK","accessed":"2026-11-19"},{"title":"Adult IV adrenaline: named concentrations, dilution and monitoring","url":"https://www.rightdecisions.scot.nhs.uk/media/ei1jmppt/adult-adrenaline_epinephrine-intravenous-version-9.pdf","publisher":"NHS Scotland / Right Decisions","accessed":"2026-11-19"}]}'::jsonb THEN
    NULL;
  ELSIF existing = '{"adult_bolus_dose":"• Cardiac arrest: 1 mg IV (10 mL of 1:10,000 solution). Repeat every 3-5 minutes as per Resuscitation Council UK guidelines.\n• Anaphylaxis: 500 micrograms IM of 1:1,000 solution. Repeat every 5 minutes if needed. 300 micrograms IM if frail, elderly or weight 30-59 kg (BNF/RCUK).\n• Profound hypotension (anaesthetic practice): 10-100 micrograms IV of 1:10,000 solution titrated to effect (e.g., 10-20 micrograms increments).","dosing":"• Adult Bolus:\n    • Cardiac arrest: 1 mg IV\n    • Anaphylaxis: 500 micrograms IM (300 micrograms IM if frail/elderly/30-59kg)\n    • Profound hypotension (anaesthetic practice): 10-100 micrograms IV\n• Adult Infusion: Initially 0.01-0.1 micrograms/kg/minute, titrated to response.\n• Paediatric Bolus:\n    • Cardiac arrest: 10 micrograms/kg IV/IO (0.1 mL/kg of 1:10,000 solution) up to 1 mg. Repeat every 3-5 minutes.\n    • Anaphylaxis IM (1:1,000 solution):\n        • <6 months: 150 micrograms\n        • 6 months - <6 years: 150 micrograms\n        • 6 - <12 years: 300 micrograms\n        • ≥12 years: 500 micrograms\n       Repeat every 5 minutes if needed.\n• Paediatric Infusion: 0.05-1 micrograms/kg/minute (typical range in critical care), titrated to effect.","key_warning":"Ensure correct concentration for intended route: 1:1,000 for IM, 1:10,000 for IV bolus.","preparation":"• Infusion (typical critical care dilution): Dilute 4 mg adrenaline in 50 mL 5% glucose or 0.9% sodium chloride = 80 micrograms/mL (e.g., use 2 mL of 1 mg/mL adrenaline).\n• Anaphylaxis IM: Undiluted 1 mg/mL (1:1,000 solution) for IM injection.\n• IV bolus (severe anaphylaxis / profound hypotension): Use 1 mg in 10 mL pre-filled syringe (0.1 mg/mL, 1:10,000 solution). If using 1 mg/mL ampoule, dilute 1 mL of 1 mg/mL adrenaline with 9 mL 0.9% sodium chloride to 0.1 mg/mL.","infusion_standard":{"amount_mg":5,"diluent_ml":50,"unit":"mcg/kg/min","weight_based":true},"sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Adrenaline (epinephrine) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=adrenaline"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Adrenaline (epinephrine) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=adrenaline"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Adrenaline (epinephrine) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=adrenaline"},{"accessed":"2026-09-13","publisher":"Critical Care Medicine / SCCM–ESICM","title":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021","url":"https://doi.org/10.1097/CCM.0000000000005337"}]}'::jsonb THEN
    UPDATE public.drugs SET adult_bolus_dose = 'Adult cardiac arrest: 1 mg IV/IO of 0.1 mg/mL under the adult ALS algorithm, repeated every 3–5 minutes. Follow the rhythm-specific timing of the first dose.
Adults with suspected anaphylaxis and a pulse: give 500 micrograms IM (0.5 mL of 1 mg/mL) in the anterolateral thigh. If airway, breathing or circulation problems persist, repeat after 5 minutes. In refractory anaphylaxis seek expert help for a monitored IV adrenaline infusion. An IV bolus in a patient with a pulse is restricted to appropriately experienced clinicians in an appropriate specialist setting.
For perioperative anaphylaxis or vasopressor support during anaesthesia, use the dedicated monitored specialist pathway.',
      dosing = 'Adult cardiac arrest: 1 mg IV/IO of 0.1 mg/mL under the adult ALS algorithm, repeated every 3–5 minutes. Follow the rhythm-specific timing of the first dose.
Adults with suspected anaphylaxis and a pulse: give 500 micrograms IM (0.5 mL of 1 mg/mL) in the anterolateral thigh. If airway, breathing or circulation problems persist, repeat after 5 minutes. In refractory anaphylaxis seek expert help for a monitored IV adrenaline infusion. An IV bolus in a patient with a pulse is restricted to appropriately experienced clinicians in an appropriate specialist setting.
Paediatric anaphylaxis with a pulse, IM 1 mg/mL: under 6 months 100–150 micrograms; 6 months to under 6 years 150 micrograms; 6–12 years 300 micrograms; over 12 years 500 micrograms, or 300 micrograms for a small or prepubertal child. Repeat after 5 minutes for persistent airway, breathing or circulation problems.
Paediatric cardiac arrest outside the newborn-at-birth pathway: 10 micrograms/kg IV/IO (0.1 mL/kg of 0.1 mg/mL), maximum 1 mg, every 3–5 minutes according to the PALS algorithm. Titrate vasoactive infusions in critical care to the specific indication, haemodynamics and local concentration protocol.',
      key_warning = 'Confirm the route, concentration in mg/mL and indication. IM anaphylaxis uses 1 mg/mL. Adult cardiac arrest uses 0.1 mg/mL for a 1 mg IV/IO dose. Never give an IM-size dose intravenously to a patient with a pulse.',
      preparation = 'Adult critical-care infusion example from the NHS injectable-medicines guide: 4 mg in a FINAL volume of 50 mL gives 80 micrograms/mL. Using 1 mg/mL stock, withdraw 4 mL and add compatible diluent to a final volume of 50 mL. Prefer a ready-prepared infusion where available. Check the actual label, access and local policy before programming the pump. This concentration is separate from the RCUK refractory-anaphylaxis infusion protocol.
For IM anaphylaxis use 1 mg/mL undiluted. For IV/IO cardiac-arrest dosing, use the labelled 0.1 mg/mL solution. Administration to a patient with a pulse requires an indication-specific specialist protocol.',
      infusion_standard = '{"amount_mg":4,"diluent_ml":50,"unit":"mcg/kg/min","weight_based":true,"note":"NHS critical-care example: 4 mg in FINAL 50 mL = 80 micrograms/mL. Verify actual concentration."}'::jsonb,
      sources = '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Adrenaline (epinephrine) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=adrenaline"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Adrenaline (epinephrine) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=adrenaline"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Adrenaline (epinephrine) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=adrenaline"},{"accessed":"2026-09-13","publisher":"Critical Care Medicine / SCCM–ESICM","title":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021","url":"https://doi.org/10.1097/CCM.0000000000005337"},{"title":"Adult resuscitation in special circumstances, 2025: anaphylaxis","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines","publisher":"Resuscitation Council UK","accessed":"2026-11-19"},{"title":"Emergency treatment of anaphylaxis: IM dosing by age, repeat dose and refractory treatment","url":"https://www.resus.org.uk/sites/default/files/2021-05/Emergency%20Treatment%20of%20Anaphylaxis%20May%202021_0.pdf","publisher":"Resuscitation Council UK","accessed":"2026-11-19"},{"title":"Adult IV adrenaline: named concentrations, dilution and monitoring","url":"https://www.rightdecisions.scot.nhs.uk/media/ei1jmppt/adult-adrenaline_epinephrine-intravenous-version-9.pdf","publisher":"NHS Scotland / Right Decisions","accessed":"2026-11-19"}]'::jsonb WHERE id='a03049d0-115e-4b01-915d-10c0a73910eb'::uuid AND slug='adrenaline';
  ELSE
    RAISE EXCEPTION 'Unexpected editorial drift for drug adrenaline; no changes committed';
  END IF;
  SELECT jsonb_build_object('adult_bolus_dose', d.adult_bolus_dose, 'infusion_range', d.infusion_range, 'key_warning', d.key_warning, 'preparation', d.preparation, 'sources', d.sources) INTO STRICT existing FROM public.drugs AS d WHERE d.id='85c6ffa5-0b6e-4379-937f-46b18e99835b'::uuid AND d.slug='calcium-chloride' FOR UPDATE;
  IF existing = '{"adult_bolus_dose":"• Adult severe acute hypocalcaemia, Society for Endocrinology: calcium gluconate is the preferred preparation. If calcium chloride is used as an alternative, use a central line and confirm the formulation. Give a loading dose equivalent to 2.2–4.4 mmol elemental calcium over 10 minutes, with ECG monitoring. Reassess and repeat according to symptoms and monitoring.\n• Adult severe hyperkalaemia with ECG changes (RCUK 2025): 10 mL of 10% calcium chloride (approximately 6.8 mmol Ca²⁺) IV over 5 minutes, with ECG monitoring and reassessment under the emergency protocol. Calcium stabilises the myocardium but does not lower serum potassium; give indicated potassium-lowering treatment as well.\n• Adult hyperkalaemic cardiac arrest (RCUK 2025): 10 mL of 10% calcium chloride IV during ALS. RCUK also recommends sodium bicarbonate 50 mmol IV for this specific situation; use separate lines or flush between the drugs. This is an indication-specific regimen, not routine calcium for every cardiac arrest.\n• Calcium channel blocker overdose: 10 mL of 10% solution (6.8 mmol Ca²⁺) IV over 5–10 minutes, repeated if necessary and guided by clinical response and calcium levels.\n• Magnesium toxicity: Initially 10 mL of 10% solution (6.8 mmol Ca²⁺) IV over 5–10 minutes. May be repeated.","infusion_range":"In adult severe acute hypocalcaemia, the Society for Endocrinology uses an initial maintenance infusion of 1.1–2.2 mmol of elemental calcium per hour following the loading dose. Titrate against serial calcium, ECG and clinical response while treating the cause. Check the exact salt, concentration and final volume. Seek renal specialist guidance for advanced renal failure/dialysis. For this indication calcium chloride requires central access.","key_warning":"Calcium chloride can cause severe tissue injury after extravasation. The Society for Endocrinology requires central administration when it replaces gluconate in adult acute hypocalcaemia. Other emergencies have indication-specific vascular-access protocols.","preparation":"Check both the named salt and the elemental-calcium amount on the exact product. Concentrations of calcium chloride vary. Use central access for adult hypocalcaemia replacement and the indication-specific emergency protocol for other indications. Avoid mixing with bicarbonate, phosphate or sulfate solutions. Observe the product restriction on ceftriaxone, especially in neonates.","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Calcium chloride 10% — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=calcium+chloride"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Calcium chloride 10% — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=calcium+chloride"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Calcium chloride 10% — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=calcium+chloride"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc)","reviewNote":"Supports this named product''s dihydrate salt and concentration; not whole-monograph or paediatric dosing verification. Sections4.4–4.5 separately checked1November2026 support the ceftriaxone/calcium sequential rules and the specifically described continuous-TPN situation; these are not general simultaneous-infusion permission.","revision":"2025-04-04","section":"2; 4.4–4.5 ceftriaxone compatibility","title":"Calcium Chloride 10% w/v pre-filled syringe — UK SmPC, composition","url":"https://www.medicines.org.uk/emc/product/4126/smpc"},{"accessed":"2026-11-01","publisher":"MHRA","reviewNote":"Supports equivalent elemental calcium: 10 mL calcium chloride 10% contains 6.8 mmol. Indication and administration rate must be assessed separately.","revision":"2023-06-27","title":"Calcium chloride/calcium gluconate: underdosing risk in severe hyperkalaemia","url":"https://www.gov.uk/drug-safety-update/calcium-chloride-calcium-gluconate-potential-risk-of-underdosing-with-calcium-gluconate-in-severe-hyperkalaemia"},{"accessed":"2026-11-01","publisher":"Resuscitation Council UK","reviewNote":"Supports the specified adult hyperkalaemia and hyperkalaemic-arrest regimens only; not all calcium indications.","revision":"2025-10-27","section":"Hyperkalaemia","title":"RCUK 2025 Special circumstances — adult hyperkalaemia","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines"},{"accessed":"2026-11-01","publisher":"Resuscitation Council UK","reviewNote":"Distinguishes perfusing children with ECG conduction abnormalities from hyperkalaemic arrest. The no-calcium recommendation is specific to paediatric hyperkalaemic arrest; other indication-specific calcium treatment remains separate.","revision":"2025-10-27","section":"Hyperkalaemia; Other metabolic derangements","title":"RCUK 2025 Paediatric Life Support — hyperkalaemia","url":"https://www.resus.org.uk/cy/node/36439"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc)","reviewNote":"Supports the specified neonatal boundaries, calcium/ceftriaxone administration restrictions, product-specific continuous-TPN exception, lidocaine route and probenecid correction. Does not certify other drug doses or the whole monograph.","revision":"2026-04-21","section":"4.2–4.5","title":"Ceftriaxone 1 g powder for injection/infusion — hameln UK SmPC","url":"https://www.medicines.org.uk/emc/product/102127/smpc"},{"title":"Emergency management of acute hypocalcaemia in adults: calcium salt equivalence and elemental-calcium targets (2019 addendum)","url":"https://doi.org/10.1530/EC-16-0056a","publisher":"Society for Endocrinology","accessed":"2026-11-19"}]}'::jsonb THEN
    NULL;
  ELSIF existing = '{"adult_bolus_dose":"• Symptomatic hypocalcaemia: 5–10 mL of 10% solution (3.4–6.8 mmol Ca²⁺) IV over 5–10 minutes, repeated as needed based on calcium levels and clinical response.\n• Adult severe hyperkalaemia with ECG changes (RCUK 2025): 10 mL of 10% calcium chloride (approximately 6.8 mmol Ca²⁺) IV over 5 minutes, with ECG monitoring and reassessment under the emergency protocol. Calcium stabilises the myocardium but does not lower serum potassium; give indicated potassium-lowering treatment as well.\n• Adult hyperkalaemic cardiac arrest (RCUK 2025): 10 mL of 10% calcium chloride IV during ALS. RCUK also recommends sodium bicarbonate 50 mmol IV for this specific situation; use separate lines or flush between the drugs. This is an indication-specific regimen, not routine calcium for every cardiac arrest.\n• Calcium channel blocker overdose: 10 mL of 10% solution (6.8 mmol Ca²⁺) IV over 5–10 minutes, repeated if necessary and guided by clinical response and calcium levels.\n• Magnesium toxicity: Initially 10 mL of 10% solution (6.8 mmol Ca²⁺) IV over 5–10 minutes. May be repeated.","infusion_range":"• Symptomatic hypocalcaemia: May follow bolus with continuous infusion. Typical adult infusion starting dose is 0.07–0.17 mmol Ca²⁺/kg/hour, adjusted to maintain calcium levels. (BNF states 0.068-0.136 mmol/kg/hr for hypocalcaemia). Example: 10 mL of 10% Calcium Chloride in 90 mL 0.9% Sodium Chloride or 5% Glucose for a concentration of 0.068 mmol Ca²⁺/mL.","key_warning":"Highly irritant: administer via central venous catheter or large peripheral vein only to avoid extravasation and severe tissue necrosis.","preparation":"Administer via central venous catheter or large peripheral vein. May be diluted with 0.9% sodium chloride or 5% glucose. Incompatible with bicarbonate, phosphate, and sulfate solutions. Do not mix or administer simultaneously with ceftriaxone. Example: 10 mL of 10% CaCl2 in 90 mL 0.9% NaCl = 0.068 mmol Ca²⁺/mL (0.68 mmol/10mL).","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Calcium chloride 10% — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=calcium+chloride"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Calcium chloride 10% — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=calcium+chloride"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Calcium chloride 10% — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=calcium+chloride"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc)","reviewNote":"Supports this named product''s dihydrate salt and concentration; not whole-monograph or paediatric dosing verification. Sections4.4–4.5 separately checked1November2026 support the ceftriaxone/calcium sequential rules and the specifically described continuous-TPN situation; these are not general simultaneous-infusion permission.","revision":"2025-04-04","section":"2; 4.4–4.5 ceftriaxone compatibility","title":"Calcium Chloride 10% w/v pre-filled syringe — UK SmPC, composition","url":"https://www.medicines.org.uk/emc/product/4126/smpc"},{"accessed":"2026-11-01","publisher":"MHRA","reviewNote":"Supports equivalent elemental calcium: 10 mL calcium chloride 10% contains 6.8 mmol. Indication and administration rate must be assessed separately.","revision":"2023-06-27","title":"Calcium chloride/calcium gluconate: underdosing risk in severe hyperkalaemia","url":"https://www.gov.uk/drug-safety-update/calcium-chloride-calcium-gluconate-potential-risk-of-underdosing-with-calcium-gluconate-in-severe-hyperkalaemia"},{"accessed":"2026-11-01","publisher":"Resuscitation Council UK","reviewNote":"Supports the specified adult hyperkalaemia and hyperkalaemic-arrest regimens only; not all calcium indications.","revision":"2025-10-27","section":"Hyperkalaemia","title":"RCUK 2025 Special circumstances — adult hyperkalaemia","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines"},{"accessed":"2026-11-01","publisher":"Resuscitation Council UK","reviewNote":"Distinguishes perfusing children with ECG conduction abnormalities from hyperkalaemic arrest. The no-calcium recommendation is specific to paediatric hyperkalaemic arrest; other indication-specific calcium treatment remains separate.","revision":"2025-10-27","section":"Hyperkalaemia; Other metabolic derangements","title":"RCUK 2025 Paediatric Life Support — hyperkalaemia","url":"https://www.resus.org.uk/cy/node/36439"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc)","reviewNote":"Supports the specified neonatal boundaries, calcium/ceftriaxone administration restrictions, product-specific continuous-TPN exception, lidocaine route and probenecid correction. Does not certify other drug doses or the whole monograph.","revision":"2026-04-21","section":"4.2–4.5","title":"Ceftriaxone 1 g powder for injection/infusion — hameln UK SmPC","url":"https://www.medicines.org.uk/emc/product/102127/smpc"}]}'::jsonb THEN
    UPDATE public.drugs SET adult_bolus_dose = '• Adult severe acute hypocalcaemia, Society for Endocrinology: calcium gluconate is the preferred preparation. If calcium chloride is used as an alternative, use a central line and confirm the formulation. Give a loading dose equivalent to 2.2–4.4 mmol elemental calcium over 10 minutes, with ECG monitoring. Reassess and repeat according to symptoms and monitoring.
• Adult severe hyperkalaemia with ECG changes (RCUK 2025): 10 mL of 10% calcium chloride (approximately 6.8 mmol Ca²⁺) IV over 5 minutes, with ECG monitoring and reassessment under the emergency protocol. Calcium stabilises the myocardium but does not lower serum potassium; give indicated potassium-lowering treatment as well.
• Adult hyperkalaemic cardiac arrest (RCUK 2025): 10 mL of 10% calcium chloride IV during ALS. RCUK also recommends sodium bicarbonate 50 mmol IV for this specific situation; use separate lines or flush between the drugs. This is an indication-specific regimen, not routine calcium for every cardiac arrest.
• Calcium channel blocker overdose: 10 mL of 10% solution (6.8 mmol Ca²⁺) IV over 5–10 minutes, repeated if necessary and guided by clinical response and calcium levels.
• Magnesium toxicity: Initially 10 mL of 10% solution (6.8 mmol Ca²⁺) IV over 5–10 minutes. May be repeated.',
      infusion_range = 'In adult severe acute hypocalcaemia, the Society for Endocrinology uses an initial maintenance infusion of 1.1–2.2 mmol of elemental calcium per hour following the loading dose. Titrate against serial calcium, ECG and clinical response while treating the cause. Check the exact salt, concentration and final volume. Seek renal specialist guidance for advanced renal failure/dialysis. For this indication calcium chloride requires central access.',
      key_warning = 'Calcium chloride can cause severe tissue injury after extravasation. The Society for Endocrinology requires central administration when it replaces gluconate in adult acute hypocalcaemia. Other emergencies have indication-specific vascular-access protocols.',
      preparation = 'Check both the named salt and the elemental-calcium amount on the exact product. Concentrations of calcium chloride vary. Use central access for adult hypocalcaemia replacement and the indication-specific emergency protocol for other indications. Avoid mixing with bicarbonate, phosphate or sulfate solutions. Observe the product restriction on ceftriaxone, especially in neonates.',
      sources = '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Calcium chloride 10% — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=calcium+chloride"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Calcium chloride 10% — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=calcium+chloride"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Calcium chloride 10% — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=calcium+chloride"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc)","reviewNote":"Supports this named product''s dihydrate salt and concentration; not whole-monograph or paediatric dosing verification. Sections4.4–4.5 separately checked1November2026 support the ceftriaxone/calcium sequential rules and the specifically described continuous-TPN situation; these are not general simultaneous-infusion permission.","revision":"2025-04-04","section":"2; 4.4–4.5 ceftriaxone compatibility","title":"Calcium Chloride 10% w/v pre-filled syringe — UK SmPC, composition","url":"https://www.medicines.org.uk/emc/product/4126/smpc"},{"accessed":"2026-11-01","publisher":"MHRA","reviewNote":"Supports equivalent elemental calcium: 10 mL calcium chloride 10% contains 6.8 mmol. Indication and administration rate must be assessed separately.","revision":"2023-06-27","title":"Calcium chloride/calcium gluconate: underdosing risk in severe hyperkalaemia","url":"https://www.gov.uk/drug-safety-update/calcium-chloride-calcium-gluconate-potential-risk-of-underdosing-with-calcium-gluconate-in-severe-hyperkalaemia"},{"accessed":"2026-11-01","publisher":"Resuscitation Council UK","reviewNote":"Supports the specified adult hyperkalaemia and hyperkalaemic-arrest regimens only; not all calcium indications.","revision":"2025-10-27","section":"Hyperkalaemia","title":"RCUK 2025 Special circumstances — adult hyperkalaemia","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines"},{"accessed":"2026-11-01","publisher":"Resuscitation Council UK","reviewNote":"Distinguishes perfusing children with ECG conduction abnormalities from hyperkalaemic arrest. The no-calcium recommendation is specific to paediatric hyperkalaemic arrest; other indication-specific calcium treatment remains separate.","revision":"2025-10-27","section":"Hyperkalaemia; Other metabolic derangements","title":"RCUK 2025 Paediatric Life Support — hyperkalaemia","url":"https://www.resus.org.uk/cy/node/36439"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc)","reviewNote":"Supports the specified neonatal boundaries, calcium/ceftriaxone administration restrictions, product-specific continuous-TPN exception, lidocaine route and probenecid correction. Does not certify other drug doses or the whole monograph.","revision":"2026-04-21","section":"4.2–4.5","title":"Ceftriaxone 1 g powder for injection/infusion — hameln UK SmPC","url":"https://www.medicines.org.uk/emc/product/102127/smpc"},{"title":"Emergency management of acute hypocalcaemia in adults: calcium salt equivalence and elemental-calcium targets (2019 addendum)","url":"https://doi.org/10.1530/EC-16-0056a","publisher":"Society for Endocrinology","accessed":"2026-11-19"}]'::jsonb WHERE id='85c6ffa5-0b6e-4379-937f-46b18e99835b'::uuid AND slug='calcium-chloride';
