  SELECT jsonb_build_object('adult_bolus_dose', d.adult_bolus_dose, 'dosing', d.dosing, 'infusion_range', d.infusion_range, 'preparation', d.preparation, 'sources', d.sources) INTO STRICT existing FROM public.drugs AS d WHERE d.id='98f36188-f9da-46bd-8542-62c7e056d53f'::uuid AND d.slug='calcium-gluconate' FOR UPDATE;
  IF existing = '{"adult_bolus_dose":"• Adult severe hyperkalaemia with ECG changes: 30 mL of 10% calcium gluconate IV over 10 minutes with ECG monitoring; reassess the ECG and follow the emergency protocol for further treatment.\n• Adult hypermagnesaemia: 10 mL of 10% calcium gluconate IV over 5–10 minutes; reassess the response.\n• Adult severe acute hypocalcaemia: dilute 10–20 mL of 10% calcium gluconate in 50–100 mL of glucose 5% and administer IV over 10 minutes with ECG monitoring. Reassess symptoms and calcium; further bolus and maintenance infusion may be needed.","dosing":"• Adult severe hyperkalaemia with ECG changes: 30 mL of 10% calcium gluconate IV over 10 minutes with ECG monitoring; reassess the ECG and follow the emergency protocol for further treatment.\n• Adult hypermagnesaemia: 10 mL of 10% calcium gluconate IV over 5–10 minutes; reassess the response.\n• Adult severe acute hypocalcaemia: dilute 10–20 mL of 10% calcium gluconate in 50–100 mL of glucose 5% and administer IV over 10 minutes with ECG monitoring. Reassess symptoms and calcium; further bolus and maintenance infusion may be needed.\n• Paediatric severe symptomatic hypocalcaemia (NHS Tayside pathway, reviewed September 2025): initial calcium 0.11 mmol/kg, equivalent to 0.5 mL/kg of 10% calcium gluconate, IV over 5–10 minutes; maximum 4.5 mmol (20 mL). Use ECG monitoring, appropriate dilution/venous access and inspect for extravasation. Reassess calcium and seek senior advice for repeat doses or infusion. Neonatal/infant exceptions require a specific specialist/product protocol; do not use 0.25–0.5 mmol/kg as a universal paediatric bolus.\n• Renal impairment: Monitor serum calcium and phosphate levels closely. Dose adjustment may be required.","infusion_range":"In adult severe acute hypocalcaemia, the Society for Endocrinology uses an initial maintenance infusion of 1.1–2.2 mmol of elemental calcium per hour following the loading dose. Titrate against serial calcium, ECG and clinical response while treating the cause. Check the exact salt, concentration and final volume. Seek renal specialist guidance for advanced renal failure/dialysis.","preparation":"Adult severe acute hypocalcaemia: use the diluted loading dose described under dosing. For maintenance the Society for Endocrinology describes 100 mL of 10% calcium gluconate in 1 L of sodium chloride 0.9% or glucose 5%, infused under observation and titrated to achieve normocalcaemia. Confirm the product and elemental-calcium delivery. For hyperkalaemia use the distinct resuscitation protocol. Do not mix with incompatible phosphate or bicarbonate preparations.","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Calcium gluconate 10% — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=calcium+gluconate"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Calcium gluconate 10% — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=calcium+gluconate"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Calcium gluconate 10% — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=calcium+gluconate"},{"accessed":"2026-10-30","publisher":"www.gov.uk","title":"Calcium gluconate 10% — targeted dosing/safety source (MHRA27June2023)","url":"https://www.gov.uk/drug-safety-update/calcium-chloride-calcium-gluconate-potential-risk-of-underdosing-with-calcium-gluconate-in-severe-hyperkalaemia"},{"accessed":"2026-10-30","publisher":"www.rightdecisions.scot.nhs.uk","title":"Calcium gluconate 10% — targeted dosing/safety source (Acute hypocalcaemia, urgent correction; reviewed 2025-09-05)","url":"https://www.rightdecisions.scot.nhs.uk/nhs-tayside-paediatrics-pathways/paediatric-endocrinology/acute-management-of-hypocalcaemia-in-children/"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc)","reviewNote":"The named product contains 2.25 mmol total calcium per 10 mL, including calcium from its excipient. The 2024 SmPC is not the adopted source for paediatric hyperkalaemic arrest: use current RCUK 2025 paediatric guidance. Sections4.3–4.5 separately checked1November2026: simultaneous IV ceftriaxone/calcium is prohibited; older-patient sequential administration requires the stated line precautions and must be avoided in hypovolaemia. Do not import a continuous-TPN exception from another product.","revision":"2024-03-07","section":"2 and 6.5 for composition/packaging; 4.2 for product-specific age-dependent hypocalcaemia context; 4.3–4.5 ceftriaxone compatibility","title":"Calcium gluconate 10% — targeted dosing/safety source (4.2: age-dependent hypocalcaemia doses and neonatal/infant exceptions; not the source of the NHS pathway’s universal initial dose)","url":"https://www.medicines.org.uk/emc/product/15226/smpc"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc)","reviewNote":"Supports the specified neonatal boundaries, calcium/ceftriaxone administration restrictions, product-specific continuous-TPN exception, lidocaine route and probenecid correction. Does not certify other drug doses or the whole monograph.","revision":"2026-04-21","section":"4.2–4.5","title":"Ceftriaxone 1 g powder for injection/infusion — hameln UK SmPC","url":"https://www.medicines.org.uk/emc/product/102127/smpc"},{"title":"Emergency management of acute hypocalcaemia in adults: calcium salt equivalence and elemental-calcium targets (2019 addendum)","url":"https://doi.org/10.1530/EC-16-0056a","publisher":"Society for Endocrinology","accessed":"2026-11-19"}]}'::jsonb THEN
    NULL;
  ELSIF existing = '{"adult_bolus_dose":"• Adult severe hyperkalaemia with ECG changes: 30 mL of 10% calcium gluconate IV over 10 minutes with ECG monitoring; reassess the ECG and follow the emergency protocol for further treatment.\n• Adult hypermagnesaemia: 10 mL of 10% calcium gluconate IV over 5–10 minutes; reassess the response.\n• Symptomatic hypocalcaemia: 10–20 mL of 10% calcium gluconate IV over 10–20 minutes.","dosing":"• Adult severe hyperkalaemia with ECG changes: 30 mL of 10% calcium gluconate IV over 10 minutes with ECG monitoring; reassess the ECG and follow the emergency protocol for further treatment.\n• Adult hypermagnesaemia: 10 mL of 10% calcium gluconate IV over 5–10 minutes; reassess the response.\n• Adult symptomatic hypocalcaemia: 10–20 mL of 10% calcium gluconate IV over 10–20 minutes. Can be followed by an infusion.\n• Paediatric severe symptomatic hypocalcaemia (NHS Tayside pathway, reviewed September 2025): initial calcium 0.11 mmol/kg, equivalent to 0.5 mL/kg of 10% calcium gluconate, IV over 5–10 minutes; maximum 4.5 mmol (20 mL). Use ECG monitoring, appropriate dilution/venous access and inspect for extravasation. Reassess calcium and seek senior advice for repeat doses or infusion. Neonatal/infant exceptions require a specific specialist/product protocol; do not use 0.25–0.5 mmol/kg as a universal paediatric bolus.\n• Renal impairment: Monitor serum calcium and phosphate levels closely. Dose adjustment may be required.","infusion_range":"• Hypocalcaemia: 0.5–2 mmol Ca2+ per hour (e.g., 22–88 mL/hour of 2.23 mmol/100 mL solution), adjusted according to serum ionised calcium levels. Requires specialist guidance and continuous ECG monitoring.","preparation":"• For IV injection: undiluted via slow IV injection into a large central or peripheral vein (max 5 mL/minute).\n• Do not mix with phosphate or bicarbonate-containing solutions due to precipitation.\n• For infusion: 90 mL 5% glucose or 0.9% sodium chloride + 10 mL 10% calcium gluconate = 2.23 mmol Ca2+/100 mL (0.0223 mmol Ca2+/mL).","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Calcium gluconate 10% — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=calcium+gluconate"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Calcium gluconate 10% — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=calcium+gluconate"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Calcium gluconate 10% — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=calcium+gluconate"},{"accessed":"2026-10-30","publisher":"www.gov.uk","title":"Calcium gluconate 10% — targeted dosing/safety source (MHRA27June2023)","url":"https://www.gov.uk/drug-safety-update/calcium-chloride-calcium-gluconate-potential-risk-of-underdosing-with-calcium-gluconate-in-severe-hyperkalaemia"},{"accessed":"2026-10-30","publisher":"www.rightdecisions.scot.nhs.uk","title":"Calcium gluconate 10% — targeted dosing/safety source (Acute hypocalcaemia, urgent correction; reviewed 2025-09-05)","url":"https://www.rightdecisions.scot.nhs.uk/nhs-tayside-paediatrics-pathways/paediatric-endocrinology/acute-management-of-hypocalcaemia-in-children/"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc)","reviewNote":"The named product contains 2.25 mmol total calcium per 10 mL, including calcium from its excipient. The 2024 SmPC is not the adopted source for paediatric hyperkalaemic arrest: use current RCUK 2025 paediatric guidance. Sections4.3–4.5 separately checked1November2026: simultaneous IV ceftriaxone/calcium is prohibited; older-patient sequential administration requires the stated line precautions and must be avoided in hypovolaemia. Do not import a continuous-TPN exception from another product.","revision":"2024-03-07","section":"2 and 6.5 for composition/packaging; 4.2 for product-specific age-dependent hypocalcaemia context; 4.3–4.5 ceftriaxone compatibility","title":"Calcium gluconate 10% — targeted dosing/safety source (4.2: age-dependent hypocalcaemia doses and neonatal/infant exceptions; not the source of the NHS pathway’s universal initial dose)","url":"https://www.medicines.org.uk/emc/product/15226/smpc"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc)","reviewNote":"Supports the specified neonatal boundaries, calcium/ceftriaxone administration restrictions, product-specific continuous-TPN exception, lidocaine route and probenecid correction. Does not certify other drug doses or the whole monograph.","revision":"2026-04-21","section":"4.2–4.5","title":"Ceftriaxone 1 g powder for injection/infusion — hameln UK SmPC","url":"https://www.medicines.org.uk/emc/product/102127/smpc"}]}'::jsonb THEN
    UPDATE public.drugs SET adult_bolus_dose = '• Adult severe hyperkalaemia with ECG changes: 30 mL of 10% calcium gluconate IV over 10 minutes with ECG monitoring; reassess the ECG and follow the emergency protocol for further treatment.
• Adult hypermagnesaemia: 10 mL of 10% calcium gluconate IV over 5–10 minutes; reassess the response.
• Adult severe acute hypocalcaemia: dilute 10–20 mL of 10% calcium gluconate in 50–100 mL of glucose 5% and administer IV over 10 minutes with ECG monitoring. Reassess symptoms and calcium; further bolus and maintenance infusion may be needed.',
      dosing = '• Adult severe hyperkalaemia with ECG changes: 30 mL of 10% calcium gluconate IV over 10 minutes with ECG monitoring; reassess the ECG and follow the emergency protocol for further treatment.
• Adult hypermagnesaemia: 10 mL of 10% calcium gluconate IV over 5–10 minutes; reassess the response.
• Adult severe acute hypocalcaemia: dilute 10–20 mL of 10% calcium gluconate in 50–100 mL of glucose 5% and administer IV over 10 minutes with ECG monitoring. Reassess symptoms and calcium; further bolus and maintenance infusion may be needed.
• Paediatric severe symptomatic hypocalcaemia (NHS Tayside pathway, reviewed September 2025): initial calcium 0.11 mmol/kg, equivalent to 0.5 mL/kg of 10% calcium gluconate, IV over 5–10 minutes; maximum 4.5 mmol (20 mL). Use ECG monitoring, appropriate dilution/venous access and inspect for extravasation. Reassess calcium and seek senior advice for repeat doses or infusion. Neonatal/infant exceptions require a specific specialist/product protocol; do not use 0.25–0.5 mmol/kg as a universal paediatric bolus.
• Renal impairment: Monitor serum calcium and phosphate levels closely. Dose adjustment may be required.',
      infusion_range = 'In adult severe acute hypocalcaemia, the Society for Endocrinology uses an initial maintenance infusion of 1.1–2.2 mmol of elemental calcium per hour following the loading dose. Titrate against serial calcium, ECG and clinical response while treating the cause. Check the exact salt, concentration and final volume. Seek renal specialist guidance for advanced renal failure/dialysis.',
      preparation = 'Adult severe acute hypocalcaemia: use the diluted loading dose described under dosing. For maintenance the Society for Endocrinology describes 100 mL of 10% calcium gluconate in 1 L of sodium chloride 0.9% or glucose 5%, infused under observation and titrated to achieve normocalcaemia. Confirm the product and elemental-calcium delivery. For hyperkalaemia use the distinct resuscitation protocol. Do not mix with incompatible phosphate or bicarbonate preparations.',
      sources = '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Calcium gluconate 10% — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=calcium+gluconate"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Calcium gluconate 10% — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=calcium+gluconate"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Calcium gluconate 10% — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=calcium+gluconate"},{"accessed":"2026-10-30","publisher":"www.gov.uk","title":"Calcium gluconate 10% — targeted dosing/safety source (MHRA27June2023)","url":"https://www.gov.uk/drug-safety-update/calcium-chloride-calcium-gluconate-potential-risk-of-underdosing-with-calcium-gluconate-in-severe-hyperkalaemia"},{"accessed":"2026-10-30","publisher":"www.rightdecisions.scot.nhs.uk","title":"Calcium gluconate 10% — targeted dosing/safety source (Acute hypocalcaemia, urgent correction; reviewed 2025-09-05)","url":"https://www.rightdecisions.scot.nhs.uk/nhs-tayside-paediatrics-pathways/paediatric-endocrinology/acute-management-of-hypocalcaemia-in-children/"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc)","reviewNote":"The named product contains 2.25 mmol total calcium per 10 mL, including calcium from its excipient. The 2024 SmPC is not the adopted source for paediatric hyperkalaemic arrest: use current RCUK 2025 paediatric guidance. Sections4.3–4.5 separately checked1November2026: simultaneous IV ceftriaxone/calcium is prohibited; older-patient sequential administration requires the stated line precautions and must be avoided in hypovolaemia. Do not import a continuous-TPN exception from another product.","revision":"2024-03-07","section":"2 and 6.5 for composition/packaging; 4.2 for product-specific age-dependent hypocalcaemia context; 4.3–4.5 ceftriaxone compatibility","title":"Calcium gluconate 10% — targeted dosing/safety source (4.2: age-dependent hypocalcaemia doses and neonatal/infant exceptions; not the source of the NHS pathway’s universal initial dose)","url":"https://www.medicines.org.uk/emc/product/15226/smpc"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc)","reviewNote":"Supports the specified neonatal boundaries, calcium/ceftriaxone administration restrictions, product-specific continuous-TPN exception, lidocaine route and probenecid correction. Does not certify other drug doses or the whole monograph.","revision":"2026-04-21","section":"4.2–4.5","title":"Ceftriaxone 1 g powder for injection/infusion — hameln UK SmPC","url":"https://www.medicines.org.uk/emc/product/102127/smpc"},{"title":"Emergency management of acute hypocalcaemia in adults: calcium salt equivalence and elemental-calcium targets (2019 addendum)","url":"https://doi.org/10.1530/EC-16-0056a","publisher":"Society for Endocrinology","accessed":"2026-11-19"}]'::jsonb WHERE id='98f36188-f9da-46bd-8542-62c7e056d53f'::uuid AND slug='calcium-gluconate';
  ELSE
    RAISE EXCEPTION 'Unexpected editorial drift for drug calcium-gluconate; no changes committed';
  END IF;
  SELECT jsonb_build_object('preparation', d.preparation) INTO STRICT existing FROM public.drugs AS d WHERE d.id='82a49209-496a-4f81-9ce5-23e4c5fc5c67'::uuid AND d.slug='glyceryl-trinitrate' FOR UPDATE;
  IF existing = '{"preparation":"Named product Glyceryl Trinitrate 1 mg/mL solution for infusion (emc 6296): 50 mL contains 50 mg. It can be administered undiluted by slow IV infusion using the manufacturer-specified compatible pump, syringe and tubing. If using the SmPC diluted preparation, add 50 mL of this 1 mg/mL product to 450 mL of a compatible vehicle: 50 mg in a FINAL 500 mL = 100 micrograms/mL. Verify the actual concentration and device before setting the rate; monitor haemodynamics continuously."}'::jsonb THEN
    NULL;
  ELSIF existing = '{"preparation":"IV Infusion: Dilute 50 mg in 50 mL 5% glucose or 0.9% sodium chloride to 1 mg/mL. E.g., 50 mg (5 mL of 10 mg/5mL ampoule) into 45 mL diluent."}'::jsonb THEN
    UPDATE public.drugs SET preparation = 'Named product Glyceryl Trinitrate 1 mg/mL solution for infusion (emc 6296): 50 mL contains 50 mg. It can be administered undiluted by slow IV infusion using the manufacturer-specified compatible pump, syringe and tubing. If using the SmPC diluted preparation, add 50 mL of this 1 mg/mL product to 450 mL of a compatible vehicle: 50 mg in a FINAL 500 mL = 100 micrograms/mL. Verify the actual concentration and device before setting the rate; monitor haemodynamics continuously.' WHERE id='82a49209-496a-4f81-9ce5-23e4c5fc5c67'::uuid AND slug='glyceryl-trinitrate';
  ELSE
    RAISE EXCEPTION 'Unexpected editorial drift for drug glyceryl-trinitrate; no changes committed';
  END IF;
  SELECT jsonb_build_object('indication_oneliner', d.indication_oneliner, 'adult_bolus_dose', d.adult_bolus_dose, 'infusion_range', d.infusion_range, 'dosing', d.dosing, 'preparation', d.preparation, 'key_warning', d.key_warning, 'monitoring', d.monitoring, 'contraindications', d.contraindications, 'sources', d.sources) INTO STRICT existing FROM public.drugs AS d WHERE d.id='594de4a8-3346-43b0-bf49-cbfd32a4531a'::uuid AND d.slug='oxytocin' FOR UPDATE;
  IF existing = '{"indication_oneliner":"Induction or augmentation of labour, prevention or treatment of uterine atony and postpartum haemorrhage, and selected specialist pregnancy indications.","adult_bolus_dose":"Active third stage after vaginal birth (NICE NG235): discuss uterotonic options. Oxytocin options include 10 units IM using a preparation licensed for IM administration, or 5 units by slow IV administration over 3–5 minutes in women who received oxytocin during labour. After caesarean birth NICE recommends offering IV carbetocin for prophylaxis. If oxytocin is selected, check the route and speed for the exact product.\nNamed hameln 10 IU/mL infusion concentrate (emc 1971): dilute for IV infusion; never give by IV bolus or IM. For treatment of postpartum uterine haemorrhage the product specifies 5 units over 5 minutes; in severe cases follow with 5–20 units in 500 mL electrolyte-containing diluent titrated to uterine tone. Activate the obstetric haemorrhage pathway and select additional uterotonics according to prior exposure, contraindications and response.","infusion_range":"Labour induction/augmentation: for the named product begin at 1–4 milliunits/minute IV. In first-stage labour NICE specifies at least 30 minutes between increments. Titrate to uterine activity and monitor continuously by CTG; reduce or stop for excessive contraction frequency and stop immediately for a pathological trace. The product recommends a maximum of 20 milliunits/minute at term and reassessment if contractions are not established after 5 units. Use a specialist local protocol for different gestations/indications.\nNamed hameln 10 IU/mL infusion concentrate (emc 1971): dilute for IV infusion; never give by IV bolus or IM. For treatment of postpartum uterine haemorrhage the product specifies 5 units over 5 minutes; in severe cases follow with 5–20 units in 500 mL electrolyte-containing diluent titrated to uterine tone. Activate the obstetric haemorrhage pathway and select additional uterotonics according to prior exposure, contraindications and response.","dosing":"Active third stage after vaginal birth (NICE NG235): discuss uterotonic options. Oxytocin options include 10 units IM using a preparation licensed for IM administration, or 5 units by slow IV administration over 3–5 minutes in women who received oxytocin during labour. After caesarean birth NICE recommends offering IV carbetocin for prophylaxis. If oxytocin is selected, check the route and speed for the exact product.\nNamed hameln 10 IU/mL infusion concentrate (emc 1971): dilute for IV infusion; never give by IV bolus or IM. For treatment of postpartum uterine haemorrhage the product specifies 5 units over 5 minutes; in severe cases follow with 5–20 units in 500 mL electrolyte-containing diluent titrated to uterine tone. Activate the obstetric haemorrhage pathway and select additional uterotonics according to prior exposure, contraindications and response.\nLabour induction/augmentation: for the named product begin at 1–4 milliunits/minute IV. In first-stage labour NICE specifies at least 30 minutes between increments. Titrate to uterine activity and monitor continuously by CTG; reduce or stop for excessive contraction frequency and stop immediately for a pathological trace. The product recommends a maximum of 20 milliunits/minute at term and reassessment if contractions are not established after 5 units. Use a specialist local protocol for different gestations/indications.\nFor incomplete, inevitable or missed abortion when this product is indicated, its labelled regimen is 5 units by IV infusion over 5 minutes, with specialist-guided continuation if required.","preparation":"For the named hameln 10 IU/mL concentrate, use a compatible physiological electrolyte diluent and administer by IV infusion only. For labour, 5 units in a final 500 mL gives 10 milliunits/mL. Select the exact standard concentration in local policy, document units and final volume, and verify pump programming. Use the separate postpartum regimen in dosing.","key_warning":"The named 10 IU/mL infusion concentrate requires dilution for IV infusion. An IV bolus can cause acute hypotension and tachycardia. Monitor for uterine hyperstimulation, fetal compromise and fluid overload.","monitoring":"During labour induction/augmentation monitor the fetal heart and contractions throughout using continuous CTG. Follow the NICE and local escalation pathways for excessive contractions or a pathological trace. Postpartum, assess uterine tone, bleeding and maternal haemodynamics. Monitor fluid balance and sodium when indicated, especially during prolonged infusion.","contraindications":"Check section 4.3 of the exact product. Contraindications include hypertonic uterine contractions, mechanical obstruction, fetal distress and conditions where vaginal birth is contraindicated, including a uterine scar from major surgery such as classical caesarean section. A previous lower uterine segment caesarean section requires separate obstetric assessment and heightened caution. The named product must not be started within 6 hours of vaginal prostaglandins.","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Oxytocin — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=oxytocin"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Oxytocin — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=oxytocin"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Oxytocin — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=oxytocin"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Selected formulation, route and population only. Other presentations, storage and treatment doses are not verified; no current stock availability certification.","revision":"18/11/2020","scope":"10 IU/mL concentrate for IV infusion, obstetric scope; not all injection products or storage statements.","sections":["1","2","3","4.1","4.2","10"],"title":"Oxytocin 10 IU/ml Concentrate for Solution for Infusion — UK SmPC","url":"https://www.medicines.org.uk/emc/product/1971/smpc"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"D125: named-product route/container/storage clarification only; other formulations and whole-monograph dosing are not certified.","scope":"Removes an unsupported universal room-temperature storage allowance while retaining product-specific scope. It does not convert or certify the separate mixed-product dosing regimens.","sections":["1","2","3","6.4","6.5"],"title":"Oxytocin 10 IU/ml Concentrate for Solution for Infusion — UK SmPC: named-product presentation and storage","url":"https://www.medicines.org.uk/emc/product/1971/smpc"},{"title":"NICE NG235 Intrapartum care: oxytocin monitoring, third-stage options and postpartum haemorrhage pathway","url":"https://www.nice.org.uk/guidance/ng235/chapter/recommendations","publisher":"NICE","accessed":"2026-11-19"}]}'::jsonb THEN
    NULL;
  ELSIF existing = '{"indication_oneliner":"Induction/augmentation of labour; prevention/treatment of PPH; inevitable/incomplete abortion; diagnostic test for foetal reserve.","adult_bolus_dose":"• PPH prophylaxis (vaginal delivery): 5 units slow IV over 1 minute OR 10 units IM.\n• PPH prophylaxis (Caesarean section): 5 units slow IV over 1 minute (anaesthetic practice, followed by infusion).\n• Inevitable/incomplete abortion: 5 units slow IV over 5 minutes.","infusion_range":"• Labour induction/augmentation: Initially 0.5–4 milliunits/minute, increased progressively by 1–2 milliunits/minute at intervals of 20–40 minutes until satisfactory contraction pattern. Max 20 milliunits/minute. Total dose should not exceed 5 units over 8 hours or 10 units over 24 hours.\n• PPH treatment: 20–40 units in 500 mL 0.9% sodium chloride or 5% glucose at a rate to control uterine atony (e.g., 125 mL/hour for 4 hours). Max 3 litres oxytocin-containing fluids.","dosing":"• PPH prophylaxis (vaginal delivery): 5 units slow IV over 1 minute OR 10 units IM.\n• PPH prophylaxis (Caesarean section): 5 units slow IV over 1 minute (anaesthetic practice). Follow with 30 units in 500 mL 0.9% sodium chloride or 5% glucose over 4 hours (anaesthetic practice).\n• PPH treatment: 5–10 units slow IV over 1 minute, followed by 20–40 units in 500 mL infusion at a rate to control uterine atony (e.g., over 1–4 hours). Maximum 3 litres oxytocin-containing fluids.\n• Labour induction/augmentation: Start 0.5–4 milliunits/minute, increase by 1–2 milliunits/minute every 20–40 minutes until target contraction pattern. Maximum 20 milliunits/minute. Total dose should not exceed 5 units over 8 hours or 10 units over 24 hours.\n• Inevitable/incomplete abortion: 5 units slow IV over 5 minutes as a single dose.\n• Diagnostic test for foetal reserve (Stress Test): 2.5–5 milliunits/minute titrated to produce 3 contractions in 10 minutes.\n• Paediatrics: Not indicated.\n• Renal/Hepatic impairment: No specific dosage adjustments; use caution to avoid fluid overload in renal impairment, monitor fluid balance and electrolytes.","preparation":"• For infusion (induction/augmentation): Dilute 5 units in 500 mL 0.9% sodium chloride or 5% glucose = 10 milliunits/mL.\n• For PPH prophylaxis/treatment: Dilute 10 units in 500 mL 0.9% sodium chloride or 5% glucose = 20 milliunits/mL.","key_warning":"Rapid IV bolus can cause severe hypotension and reflex tachycardia; always administer slowly to avoid profound cardiovascular effects.","monitoring":"• Clinical: Continuous monitoring of uterine tone and vaginal bleeding (postpartum). Continuous cardiotocography (CTG) during labour induction/augmentation initially, then foetal heart rate and contractions.\n• Cardiovascular: Heart rate, blood pressure.\n• Fluid balance: Strict monitoring, especially with high-dose or prolonged infusions, to detect water intoxication/hyponatraemia. Monitor electrolytes (sodium), particularly with prolonged use or high doses.\n• Foetal: Foetal heart rate and pattern during labour induction/augmentation.","contraindications":"Hypersensitivity to oxytocin. Hypertonic uterine contractions, mechanical obstruction to delivery, foetal distress where delivery is not imminent, placenta praevia, vasa praevia, cord presentation or prolapse. Avoid prolonged use in uterine inertia, severe pre-eclampsia, or severe cardiovascular disorder. History of uterine surgery, including previous Caesarean section, requires caution. Not for elective induction of labour if foetal distress, prematurity, abnormal presentation, or multiple pregnancy.","sources":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Oxytocin — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=oxytocin"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Oxytocin — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=oxytocin"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Oxytocin — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=oxytocin"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Selected formulation, route and population only. Other presentations, storage and treatment doses are not verified; no current stock availability certification.","revision":"18/11/2020","scope":"10 IU/mL concentrate for IV infusion, obstetric scope; not all injection products or storage statements.","sections":["1","2","3","4.1","4.2","10"],"title":"Oxytocin 10 IU/ml Concentrate for Solution for Infusion — UK SmPC","url":"https://www.medicines.org.uk/emc/product/1971/smpc"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"D125: named-product route/container/storage clarification only; other formulations and whole-monograph dosing are not certified.","scope":"Removes an unsupported universal room-temperature storage allowance while retaining product-specific scope. It does not convert or certify the separate mixed-product dosing regimens.","sections":["1","2","3","6.4","6.5"],"title":"Oxytocin 10 IU/ml Concentrate for Solution for Infusion — UK SmPC: named-product presentation and storage","url":"https://www.medicines.org.uk/emc/product/1971/smpc"}]}'::jsonb THEN
    UPDATE public.drugs SET indication_oneliner = 'Induction or augmentation of labour, prevention or treatment of uterine atony and postpartum haemorrhage, and selected specialist pregnancy indications.',
      adult_bolus_dose = 'Active third stage after vaginal birth (NICE NG235): discuss uterotonic options. Oxytocin options include 10 units IM using a preparation licensed for IM administration, or 5 units by slow IV administration over 3–5 minutes in women who received oxytocin during labour. After caesarean birth NICE recommends offering IV carbetocin for prophylaxis. If oxytocin is selected, check the route and speed for the exact product.
Named hameln 10 IU/mL infusion concentrate (emc 1971): dilute for IV infusion; never give by IV bolus or IM. For treatment of postpartum uterine haemorrhage the product specifies 5 units over 5 minutes; in severe cases follow with 5–20 units in 500 mL electrolyte-containing diluent titrated to uterine tone. Activate the obstetric haemorrhage pathway and select additional uterotonics according to prior exposure, contraindications and response.',
      infusion_range = 'Labour induction/augmentation: for the named product begin at 1–4 milliunits/minute IV. In first-stage labour NICE specifies at least 30 minutes between increments. Titrate to uterine activity and monitor continuously by CTG; reduce or stop for excessive contraction frequency and stop immediately for a pathological trace. The product recommends a maximum of 20 milliunits/minute at term and reassessment if contractions are not established after 5 units. Use a specialist local protocol for different gestations/indications.
Named hameln 10 IU/mL infusion concentrate (emc 1971): dilute for IV infusion; never give by IV bolus or IM. For treatment of postpartum uterine haemorrhage the product specifies 5 units over 5 minutes; in severe cases follow with 5–20 units in 500 mL electrolyte-containing diluent titrated to uterine tone. Activate the obstetric haemorrhage pathway and select additional uterotonics according to prior exposure, contraindications and response.',
      dosing = 'Active third stage after vaginal birth (NICE NG235): discuss uterotonic options. Oxytocin options include 10 units IM using a preparation licensed for IM administration, or 5 units by slow IV administration over 3–5 minutes in women who received oxytocin during labour. After caesarean birth NICE recommends offering IV carbetocin for prophylaxis. If oxytocin is selected, check the route and speed for the exact product.
Named hameln 10 IU/mL infusion concentrate (emc 1971): dilute for IV infusion; never give by IV bolus or IM. For treatment of postpartum uterine haemorrhage the product specifies 5 units over 5 minutes; in severe cases follow with 5–20 units in 500 mL electrolyte-containing diluent titrated to uterine tone. Activate the obstetric haemorrhage pathway and select additional uterotonics according to prior exposure, contraindications and response.
Labour induction/augmentation: for the named product begin at 1–4 milliunits/minute IV. In first-stage labour NICE specifies at least 30 minutes between increments. Titrate to uterine activity and monitor continuously by CTG; reduce or stop for excessive contraction frequency and stop immediately for a pathological trace. The product recommends a maximum of 20 milliunits/minute at term and reassessment if contractions are not established after 5 units. Use a specialist local protocol for different gestations/indications.
For incomplete, inevitable or missed abortion when this product is indicated, its labelled regimen is 5 units by IV infusion over 5 minutes, with specialist-guided continuation if required.',
      preparation = 'For the named hameln 10 IU/mL concentrate, use a compatible physiological electrolyte diluent and administer by IV infusion only. For labour, 5 units in a final 500 mL gives 10 milliunits/mL. Select the exact standard concentration in local policy, document units and final volume, and verify pump programming. Use the separate postpartum regimen in dosing.',
      key_warning = 'The named 10 IU/mL infusion concentrate requires dilution for IV infusion. An IV bolus can cause acute hypotension and tachycardia. Monitor for uterine hyperstimulation, fetal compromise and fluid overload.',
      monitoring = 'During labour induction/augmentation monitor the fetal heart and contractions throughout using continuous CTG. Follow the NICE and local escalation pathways for excessive contractions or a pathological trace. Postpartum, assess uterine tone, bleeding and maternal haemodynamics. Monitor fluid balance and sodium when indicated, especially during prolonged infusion.',
      contraindications = 'Check section 4.3 of the exact product. Contraindications include hypertonic uterine contractions, mechanical obstruction, fetal distress and conditions where vaginal birth is contraindicated, including a uterine scar from major surgery such as classical caesarean section. A previous lower uterine segment caesarean section requires separate obstetric assessment and heightened caution. The named product must not be started within 6 hours of vaginal prostaglandins.',
      sources = '[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Oxytocin — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=oxytocin"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Oxytocin — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=oxytocin"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Oxytocin — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=oxytocin"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Selected formulation, route and population only. Other presentations, storage and treatment doses are not verified; no current stock availability certification.","revision":"18/11/2020","scope":"10 IU/mL concentrate for IV infusion, obstetric scope; not all injection products or storage statements.","sections":["1","2","3","4.1","4.2","10"],"title":"Oxytocin 10 IU/ml Concentrate for Solution for Infusion — UK SmPC","url":"https://www.medicines.org.uk/emc/product/1971/smpc"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"D125: named-product route/container/storage clarification only; other formulations and whole-monograph dosing are not certified.","scope":"Removes an unsupported universal room-temperature storage allowance while retaining product-specific scope. It does not convert or certify the separate mixed-product dosing regimens.","sections":["1","2","3","6.4","6.5"],"title":"Oxytocin 10 IU/ml Concentrate for Solution for Infusion — UK SmPC: named-product presentation and storage","url":"https://www.medicines.org.uk/emc/product/1971/smpc"},{"title":"NICE NG235 Intrapartum care: oxytocin monitoring, third-stage options and postpartum haemorrhage pathway","url":"https://www.nice.org.uk/guidance/ng235/chapter/recommendations","publisher":"NICE","accessed":"2026-11-19"}]'::jsonb WHERE id='594de4a8-3346-43b0-bf49-cbfd32a4531a'::uuid AND slug='oxytocin';
